NAME = 'Street Blosm / Prepare Section geometry v1'


def index(g):
    return V(g, g.node('GeometryNodeInputIndex').outputs[0])


def view(g, geo, tag):
    n = g.node('GeometryNodeSeparateGeometry', 'Blosm input table '+str(tag))
    n.domain = 'POINT'
    g.bind(geo, n.inputs['Geometry'])
    g.bind(rm.equal(g, named(g, 's2_record_type', 'INT'), tag), n.inputs['Selection'])
    return V(g, n.outputs['Selection'])


def sample(g, geo, value, at, kind='FLOAT', domain='POINT'):
    n = g.node('GeometryNodeSampleIndex', 'Explicit '+domain+' lookup')
    n.data_type = kind; n.domain = domain; n.clamp = False
    g.bind(geo, n.inputs['Geometry']); g.bind(value, n.inputs['Value'])
    g.bind(at, n.inputs['Index'])
    return V(g, n.outputs['Value'])


def stat(g, geo, value, operation='Max'):
    n = g.node('GeometryNodeAttributeStatistic', operation+' over prepared records')
    n.data_type = 'FLOAT'; n.domain = 'POINT'
    g.bind(geo, n.inputs['Geometry']); g.bind(value, n.inputs['Attribute'])
    return V(g, n.outputs[operation])


def points(g, count):
    n = g.node('GeometryNodeMeshLine', 'Allocate runtime records')
    n.mode = 'OFFSET'; g.bind(count, n.inputs['Count'])
    n.inputs['Offset'].default_value = (0., 0., 0.)
    return V(g, n.outputs['Mesh'])


def rows(g, geo, fields):
    for name, (value, kind) in fields.items():
        geo = g.store(geo, name, value, 'POINT', kind)
    return geo


def F(v): return v, 'FLOAT'
def I(v): return v, 'INT'
def B(v): return v, 'BOOLEAN'
def XYZ(g, xy): return g.xyz(*xy), 'FLOAT_VECTOR'
def add(a,b): return [x+y for x,y in zip(a,b)]
def sub(a,b): return [x-y for x,y in zip(a,b)]
def mul(a,s): return [x*s for x in a]
def dot(a,b): return a[0]*b[0]+a[1]*b[1]
