def build_corners(g, arms):
    at=index(g); n=rm.count(g,arms); nxt=g.math('FLOORED_MODULO',at+1.,n)
    t=vec(g,arms,'tangent',at); u=vec(g,arms,'tangent',nxt)
    r=vec(g,arms,'right',at); s=vec(g,arms,'right',nxt)
    a=vec(g,arms,'origin',at); b=vec(g,arms,'origin',nxt)
    wi=rm.read(g,arms,'width',at); wj=rm.read(g,arms,'width',nxt)
    radius=rm.read(g,arms,'corner_radius',at)
    tilted_i=rm.read(g,arms,'oblique',at,'BOOLEAN');tilted_j=rm.read(g,arms,'oblique',nxt,'BOOLEAN')
    any_tilt=g.math('MAXIMUM',tilted_i,tilted_j)
    axis_i,axis_j=t,u
    left=sub(a,mul(r,wi*.5));right_edge=add(b,mul(s,wj*.5))
    left=selectxy(g,tilted_i,vec(g,arms,'left_origin',at),left)
    right_edge=selectxy(g,tilted_j,vec(g,arms,'right_origin',nxt),right_edge)
    t=selectxy(g,tilted_i,vec(g,arms,'left_direction',at),t)
    u=selectxy(g,tilted_j,vec(g,arms,'right_direction',nxt),u)
    r,s=oblique.right(t),oblique.right(u)
    sine,cosine=cross(t,u),dot(t,u)
    opposite=g.math('LESS_THAN',g.math('ABSOLUTE',sine),1e-5)*g.math('LESS_THAN',cosine,0.)
    angle=g.math('ARCTAN2',sine,cosine)
    angle=choose(g,opposite,math.pi,angle)
    angle=choose(g,g.math('LESS_THAN',angle,0.),angle+math.tau,angle)
    # A bent through road gives the outside sector a reflex arm gap. Its
    # boundary is a convex fillet: reverse the radius offset, not the radius.
    side=choose(g,g.math('GREATER_THAN',angle,math.pi),-1.,1.)
    pa=sub(a,mul(r,wi*.5+side*radius)); pb=add(b,mul(s,wj*.5+side*radius))
    pa=selectxy(g,any_tilt,sub(left,mul(r,side*radius)),pa)
    pb=selectxy(g,any_tilt,add(right_edge,mul(s,side*radius)),pb)
    delta=sub(pb,pa)
    first=choose(g,opposite,0.,cross(delta,u)/sine)
    second=choose(g,opposite,0.,cross(delta,t)/sine)
    center=add(pa,mul(t,first))
    arc_start=add(center,mul(r,side*radius));arc_end=sub(center,mul(s,side*radius))
    first=choose(g,any_tilt*(1.-opposite),dot(arc_start,axis_i),first)
    second=choose(g,any_tilt*(1.-opposite),dot(arc_end,axis_j),second)
    valid=g.math('GREATER_THAN',angle,.08)*g.math('LESS_THAN',angle,math.pi*7./6.+1e-4)
    return rows(g,points(g,n),{
        'first_station':F(first),'second_station':F(second),'opposite':B(opposite),
        'center':XYZ(g,center),'radius':F(radius),'side':F(side),
        'arc_start':XYZ(g,arc_start),'arc_end':XYZ(g,arc_end),
        'start_angle':F(g.math('ARCTAN2',side*r[1],side*r[0])),
        'sweep':F(angle-math.pi),'corner_valid':B(valid),
    })


def finish_arms(g, arms, corners):
    at=index(g); prev=g.math('FLOORED_MODULO',at-1.,rm.count(g,arms))
    a=rm.read(g,corners,'first_station',at); b=rm.read(g,corners,'second_station',prev)
    d=g.math('MAXIMUM',g.math('MAXIMUM',a,b),named(g,'minimum_station'))
    d=g.math('MAXIMUM',d,.05)
    valid=named(g,'input_valid','BOOLEAN')*g.math('GREATER_THAN',named(g,'outer_station')-d,.2)
    active=rm.read(g,arms,'oblique',at,'BOOLEAN')
    section=oblique.section(g,arms,at,d)
    far_section=oblique.section(g,arms,at,rm.read(g,arms,'outer_station',at))
    valid=valid*choose(g,active,g.math('GREATER_THAN',section['gap'],.001)*
                      g.math('GREATER_THAN',far_section['gap'],.001),1.)
    fields={'inner_station':F(d),'input_valid':B(valid)}
    for name in ('origin','width','plateau_fraction','profile_shift','left_half_width','right_half_width',
                 'left_plateau_fraction','right_plateau_fraction'):
        fields[name]=XYZ(g,selectxy(g,active,section[name],vec(g,arms,name,at))) if name=='origin' else F(
            choose(g,active,section[name],rm.read(g,arms,name,at)))
    fields['profile_denominator']=F(1.-choose(g,active,section['plateau_fraction'],rm.read(g,arms,'plateau_fraction',at)))
    return rows(g,arms,fields)


def prepare_sectors(g, arms, corners):
    at=index(g); n=rm.count(g,arms); nxt=g.math('FLOORED_MODULO',at+1.,n)
    def arm(name,i=at): return rm.read(g,arms,name,i)
    ti=vec(g,arms,'tangent',at); tj=vec(g,arms,'tangent',nxt)
    ri=vec(g,arms,'right',at); rj=vec(g,arms,'right',nxt)
    oi=vec(g,arms,'origin',at); oj=vec(g,arms,'origin',nxt)
    di,dj=arm('inner_station'),arm('inner_station',nxt)
    ci=add(oi,mul(ti,di)); cj=add(oj,mul(tj,dj))
    pi=add(ci,mul(ri,arm('profile_shift')))
    pj=add(cj,mul(rj,arm('profile_shift',nxt)))
    start=sub(ci,mul(ri,arm('width')*.5)); end=add(cj,mul(rj,arm('width',nxt)*.5))
    oi=add(oi,mul(ri,arm('profile_shift')))
    oj=add(oj,mul(rj,arm('profile_shift',nxt)))
    center=vec(g,corners,'center',at); radius=rm.read(g,corners,'radius',at)
    side=rm.read(g,corners,'side',at)
    arcstart=add(center,mul(ri,side*radius)); arcend=sub(center,mul(rj,side*radius))
    tilted_i=rm.read(g,arms,'oblique',at,'BOOLEAN');tilted_j=rm.read(g,arms,'oblique',nxt,'BOOLEAN')
    any_tilt=g.math('MAXIMUM',tilted_i,tilted_j)
    arcstart=selectxy(g,any_tilt,vec(g,corners,'arc_start',at),arcstart)
    arcend=selectxy(g,any_tilt,vec(g,corners,'arc_end',at),arcend)
    opposite=rm.read(g,corners,'opposite',at,'BOOLEAN')
    h=g.math('ABSOLUTE',dot(sub(pj,pi),ti))/3.
    k1=selectxy(g,opposite,sub(pi,mul(ti,h)),add(oi,mul(ti,.4*di)))
    k2=selectxy(g,opposite,sub(pj,mul(tj,h)),add(oj,mul(tj,.4*dj)))
    k1=selectxy(g,tilted_i,sub(pi,mul(vec(g,arms,'left_direction',at),choose(g,opposite,h,.6*di))),k1)
    k2=selectxy(g,tilted_j,sub(pj,mul(vec(g,arms,'right_direction',nxt),choose(g,opposite,h,.6*dj))),k2)
    l0=length(g,sub(arcstart,start)); la=radius*g.math('ABSOLUTE',rm.read(g,corners,'sweep',at)); l2=length(g,sub(end,arcend))
    l0=choose(g,g.math('LESS_THAN',l0,1e-5),0.,l0)
    l2=choose(g,g.math('LESS_THAN',l2,1e-5),0.,l2)
    delta=sub(end,start)
    total=choose(g,opposite,length(g,delta),l0+la+l2)
    zero_i=g.math('LESS_THAN',arm('left_half_width'),1e-7)
    zero_j=g.math('LESS_THAN',arm('right_half_width',nxt),1e-7)
    return rows(g,points(g,n),{
        'record_type':I(2),'record_index':I(at),'kind':I(1),'surface_part':I(at),'flip':B(True),'grass':B(False),
        'first_arm':I(at),'second_arm':I(nxt),'sector_index':I(at),
        'prev_sector_index':I(g.math('FLOORED_MODULO',at-1.,n)),'next_sector_index':I(nxt),
        'K0':XYZ(g,pi),'K1':XYZ(g,k1),'K2':XYZ(g,k2),'K3':XYZ(g,pj),
        'K1_3':XYZ(g,mul(k1,3.)),'K2_3':XYZ(g,mul(k2,3.)),
        'boundary_start':XYZ(g,start),'boundary_end':XYZ(g,end),
        'arc_start':XYZ(g,arcstart),'arc_end':XYZ(g,arcend),'center':XYZ(g,center),
        'opposite':B(opposite),'outer_length':F(total),'line0_length':F(l0),
        'arc_length':F(la),'line2_length':F(l2),'radius':F(radius),
        'start_angle':F(rm.read(g,corners,'start_angle',at)),
        'sweep':F(rm.read(g,corners,'sweep',at)),
        'tangent':XYZ(g,ti),'right':XYZ(g,ri),'ds':F(dot(delta,ti)),'dq':F(dot(delta,ri)),
        'split_fraction':F(di/(di+dj)),'angular_mode':I(choose(g,opposite,2,1,'INT')),
        'radial_mode':I(1),'piece_start':I(at*3.),'piece_count':I(choose(g,opposite,1,3,'INT')),
        # No zero-width sector mesh. Its analytic boundary remains a side of
        # the direct-quad center and meets the raised separator plateau.
        'plateau_edge':B(zero_i*zero_j),'sector_valid':B(rm.equal(g,zero_i,zero_j)),
    })


def sampling(g, sectors, arms, cell):
    # Both sides of a sector must be sampled. A short outer circular arc can
    # accompany a much longer inner cubic, especially at a divided-road mouth.
    controls=[g.separate(named(g,'K'+str(i),'FLOAT_VECTOR'))[:2] for i in range(4)]
    speed=3.*length(g,sub(controls[1],controls[0]))
    for a,b in zip(controls[1:-1],controls[2:]):
        speed=g.math('MAXIMUM',speed,3.*length(g,sub(b,a)))
    total=named(g,'outer_length'); l0=named(g,'line0_length'); l2=named(g,'line2_length')
    la=named(g,'arc_length')
    span=g.math('MAXIMUM',total,speed)
    required=[g.math('CEIL',span*piece/(total*cell)) for piece in (l0,la,l2)]
    opposite=named(g,'opposite','BOOLEAN')
    opposite_speed=g.math('SQRT',named(g,'ds')**2+(1.875*named(g,'dq'))**2)
    fraction=named(g,'split_fraction')
    opposite_count=2.*g.math('CEIL',g.math('MAXIMUM',speed,opposite_speed)*g.math('MAXIMUM',fraction,1.-fraction)/cell)
    wanted=choose(g,opposite,opposite_count,sum(required))
    maximum=stat(g,sectors,wanted)
    nu=g.math('MAXIMUM',8.,2.*g.math('CEIL',maximum/2.))
    halfwidth=stat(g,arms,g.math('MAXIMUM',named(g,'left_half_width'),named(g,'right_half_width')))
    nv=g.math('MAXIMUM',4.,4.*g.math('CEIL',halfwidth/(4.*cell)))
    extra=g.math('MAXIMUM',nu-sum(required),0.)
    c0=required[0]+g.math('FLOOR',extra*l0/total)
    c2=required[2]+g.math('FLOOR',extra*l2/total)
    sectors=rows(g,sectors,{'nu_base':I(nu),'nv_base':I(nv),
                          'line0_count':I(c0),'line2_count':I(c2)})
    return sectors,nu,nv


def build_pieces(g, sectors):
    at=index(g); si=g.math('FLOOR',at/3.); part=g.math('FLOORED_MODULO',at,3.)
    first=rm.equal(g,part,0.); last=rm.equal(g,part,2.)
    val=lambda name:rm.read(g,sectors,name,si)
    p=lambda name:vec(g,sectors,name,si)
    opposite=rm.read(g,sectors,'opposite',si,'BOOLEAN')
    start=selectxy(g,first,p('boundary_start'),selectxy(g,last,p('arc_end'),p('arc_start')))
    end=selectxy(g,first,p('arc_start'),selectxy(g,last,p('boundary_end'),p('arc_end')))
    end=selectxy(g,opposite,p('boundary_end'),end)
    l0,la,l2,total=[val(n) for n in ('line0_length','arc_length','line2_length','outer_length')]
    c0,c2,nu=[val(n) for n in ('line0_count','line2_count','nu_base')]
    offset=choose(g,first,0.,choose(g,last,l0+la,l0))
    size=choose(g,opposite,total,choose(g,first,l0,choose(g,last,l2,la)))
    u0=choose(g,first,0.,choose(g,last,(nu-c2)/nu,c0/nu))
    u1=choose(g,first,c0/nu,choose(g,last,1.,(nu-c2)/nu))
    t0=offset/total; t1=(offset+size)/total
    return rows(g,points(g,rm.count(g,sectors)*3.),{
        'record_type':I(3),'record_index':I(at),
        'kind':I(choose(g,opposite,2,choose(g,rm.equal(g,part,1.),1,0,'INT'),'INT')),
        'offset':F(choose(g,opposite,0.,offset)),'length':F(size),
        'u0':F(u0),'u1':F(u1),'u_span':F(u1-u0),'t0':F(t0),'t1':F(t1),'t_span':F(t1-t0),
        'start':XYZ(g,start),'end':XYZ(g,end),'delta':XYZ(g,sub(end,start)),
        'center':XYZ(g,p('center')),'radius':F(val('radius')),
        'start_angle':F(val('start_angle')),'sweep':F(val('sweep')),
        'tangent':XYZ(g,p('tangent')),'right':XYZ(g,p('right')),'ds':F(val('ds')),'dq':F(val('dq')),
    })


def build_strips(g, arms, cell, nv):
    at=index(g); ai=g.math('FLOOR',at/3.); part=g.math('FLOORED_MODULO',at,3.)
    val=lambda name:rm.read(g,arms,name,ai)
    median=val('plateau_fraction'); divided=g.math('GREATER_THAN',median,0.)
    center=2.*val('profile_shift')/val('width')
    left=rm.equal(g,part,0.); grass=rm.equal(g,part,2.)
    q0=choose(g,left,-1.,choose(g,grass,center-median,center+median))
    q1=choose(g,left,center-median,choose(g,grass,center+median,1.))
    d,end=val('inner_station'),val('outer_station')
    radial=choose(g,grass,nv*.5,choose(g,divided,nv*.75,nv))
    geo=rows(g,points(g,rm.count(g,arms)*3.),{
        'record_type':I(2),'record_index':I(at),'surface_part':I(1000.+at),'kind':I(0),
        'arm':I(ai),'grass':B(grass),'flip':B(True),'nu_base':I(g.math('MAXIMUM',1.,g.math('CEIL',(end-d)/cell))),
        'nv_base':I(radial),'station0':F(d),'station1':F(end),'station_span':F(end-d),
        'q0':F(q0),'q1':F(q1),'q_span':F(q1-q0),
    })
    sep=g.node('GeometryNodeSeparateGeometry','Discard absent separator strips');sep.domain='POINT'
    g.bind(geo,sep.inputs['Geometry']);g.bind((1.-grass*(1.-divided))*g.math('GREATER_THAN',q1-q0,1e-7),sep.inputs['Selection'])
    return V(g,sep.outputs['Selection'])


def centroid(g, sectors):
    """Hub seed from exact polynomial moments of the cubic control ring.

    For half-profiles a collapsed sector's center edge follows the analytic
    plateau boundary instead. Its K controls still supply this interior seed;
    it is not claimed to be the centroid of that modified ring. The final
    positive-quad guard checks the actual Coons blocks and relaxed mesh.
    """
    k=[vec(g,sectors,'K'+str(i),index(g)) for i in range(4)]
    integral=0.; moment=[0.,0.]
    for t,w in ((.046910077030668,.118463442528095),(.230765344947158,.239314335249683),
                (.5,.284444444444444),(.769234655052842,.239314335249683),(.953089922969332,.118463442528095)):
        p=[(1-t)**3*k[0][j]+3*t*(1-t)**2*k[1][j]+3*t*t*(1-t)*k[2][j]+t**3*k[3][j] for j in (0,1)]
        d=[3*(1-t)**2*(k[1][j]-k[0][j])+6*t*(1-t)*(k[2][j]-k[1][j])+3*t*t*(k[3][j]-k[2][j]) for j in (0,1)]
        c=cross(p,d)*w;integral=integral+c;moment=[moment[j]+p[j]*c for j in (0,1)]
    area2=stat(g,sectors,integral,'Sum')
    return [2.*stat(g,sectors,m,'Sum')/(3.*area2) for m in moment],area2


def build():
    g=Graph(NAME)
    g.socket('Geometry','NodeSocketGeometry');g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    g.socket('Valid','NodeSocketBool','OUTPUT');g.socket('Diagnostic Code','NodeSocketInt','OUTPUT')
    inp=g.node('NodeGroupInput');carrier=inp.outputs['Geometry']
    tables={key:view(g,carrier,tag) for key,tag in (
        ('header',contract.HEADER),('connectors',contract.CONNECTOR),('members',contract.MEMBER),('profiles',contract.PROFILE))}
    cell=rm.read(g,tables['header'],'s2_cell_size',0)
    g.section('Section paths, signed offsets and explicit Bundle members')
    arms=build_arms(g,carrier,tables)
    g.section('Adjacent offset-line intersections and circular fillets')
    corners=build_corners(g,arms);arms=finish_arms(g,arms,corners)
    g.section('Mouths and tangent-aligned sector controls')
    sectors=prepare_sectors(g,arms,corners)
    sectors,nu,nv=sampling(g,sectors,arms,cell)
    pieces=build_pieces(g,sectors);strips=build_strips(g,arms,cell,nv)
    g.section('Control-ring centroid hub seed and geometric validity')
    hub,area2=centroid(g,sectors)
    validarms=stat(g,arms,named(g,'input_valid','BOOLEAN'),'Min')
    validcorners=stat(g,corners,named(g,'corner_valid','BOOLEAN'),'Min')
    validarea=g.math('GREATER_THAN',area2,1e-5)*stat(g,sectors,named(g,'sector_valid','BOOLEAN'),'Min')
    half=stat(g,arms,g.math('ABSOLUTE',named(g,'half_profile','INT')))
    common_rise=g.math('LESS_THAN',stat(g,arms,named(g,'rise'))-stat(g,arms,named(g,'rise'),'Min'),1e-7)
    validarms=validarms*choose(g,half,common_rise,1.)
    valid=validarms*validcorners*validarea
    code=choose(g,1.-validarms,1,choose(g,1.-validcorners,2,choose(g,1.-validarea,3,0,'INT'),'INT'),'INT')
    scale=stat(g,arms,named(g,'inner_station')+named(g,'width')*.5)
    header=rows(g,points(g,1),{'record_type':I(0),'record_index':I(0),'hub':XYZ(g,hub),
        'ceiling':F(stat(g,arms,named(g,'rise'))),'crown_weight_scale_m':F(scale),
        'crown_weight_scale_squared':F(scale*scale),'arm_count':I(rm.count(g,arms)),
        'sector_count':I(rm.count(g,sectors)),'patch_count':I(rm.count(g,sectors)+rm.count(g,strips)),
        'boundary_count':I(rm.count(g,pieces)),'input_valid':B(valid),'diagnostic_code':I(code),
        'sampling_angular':I(nu),'sampling_radial':I(nv)})
    join=g.node('GeometryNodeJoinGeometry','Backend records derived entirely in GN')
    for geo in (header,arms,sectors,strips,pieces):g.bind(geo,join.inputs['Geometry'])
    out=g.node('NodeGroupOutput');g.bind(join.outputs['Geometry'],out.inputs['Geometry'])
    g.bind(valid,out.inputs['Valid']);g.bind(code,out.inputs['Diagnostic Code'])
    g.g['scope']='One planar junction, straight local Sections, explicit single/shared smooth crowns. No baked analytic input.'
    return g.g
